const STORAGE = { cart: 'qikly_cart_v2', wishlist: 'qikly_wishlist_v2', theme: 'qikly_theme_v2' }
const money = (n) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(n) || 0)
const shortDate = (v) => v ? new Date(v).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—'
const safe = (v) => String(v ?? '')
const imgFallback = 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=900&q=80'

function getLocal(key, fallback) { try { return JSON.parse(localStorage.getItem(key) || JSON.stringify(fallback)) } catch { return fallback } }
function setLocal(key, val) { localStorage.setItem(key, JSON.stringify(val)) }
function slugify(v) { return String(v).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') }

